def dijkstra(graphe, depart):
    dist = {depart: 0}
    tas = [(0, depart)]
    while tas:
        d, ville = heapq.heappop(tas)
        if d > dist[ville]:
            continue
        for voisin, km in graphe[ville].items():
            nouvelle = d + km
            if voisin not in dist or nouvelle < dist[voisin]:
                dist[voisin] = nouvelle
                heapq.heappush(tas, (nouvelle, voisin))
    return dist

