from collections import deque

def dijkstra(graphe, depart):
    dist = {depart: 0}
    file = deque([depart])
    while file:
        ville = file.popleft()
        for voisin, km in graphe[ville].items():
            if voisin not in dist:
                dist[voisin] = dist[ville] + km
                file.append(voisin)
    return dist

